/* Types */
export type ActionPreview = {
	kind: CardKind,
	tier: Tier,
	/**  The confirm button's label: Send, Create, Delete… */
	verb: string,
	/**  Verb plus resolved target. Never argument prose. */
	title: string,
	fields: Field[],
	/**  Every shown argument past the main fields. Nothing set is dropped. */
	more: Field[],
	/**  Arguments the call passed, empties and defaults included. */
	set: number,
	/**  Arguments the tool takes: its schema's properties plus any extras passed. */
	total: number,
	risks: string[],
	pickedBy: string | null,
	recoverable: string | null,
	safer: Safer | null,
	/**  Exact-words countdown, in ms. */
	autoMs: number | null,
	revision: number,
	/**  Permission scope label, e.g. "Slack · send messages". */
	scope: string | null,
};

/**
 *  Which CLI to open in the worktree. Serde/specta so this is the one type the
 *  Tauri command and its TS binding use — no parallel enum to keep in sync.
 */
export type Agent = "claude" | "codex";

/**
 *  Streamed to the agent panel. Names follow the AG-UI protocol's tool-call
 *  lifecycle (https://docs.ag-ui.com) so the shape maps onto AI Elements' tool
 *  renderer — the vocabulary only, not the wire protocol.
 */
export type AgentEvent = 
/**  The transcript, echoed so the panel shows what it heard. */
{ kind: "runStarted"; value: string } | 
/**
 *  The batch a round intends to run, sent before the first call so a run
 *  about to send mail can still be read. Only when a round holds >1 call.
 */
{ kind: "planned"; value: PlannedCall[] } | 
/**  A parsed action awaiting dispatch. A write pauses here for confirmation. */
{ kind: "toolCall"; value: ToolCall } | 
/**
 *  The open gate was answered other than by its own buttons — the
 *  countdown, or a spoken reply — so the panel can stop asking. `false` is
 *  a decline.
 */
{ kind: "decided"; value: boolean } | { kind: "toolResult"; value: ToolResult } | 
/**
 *  The model needs something only the user can give. The run is suspended
 *  until `answer_agent`; the panel shows an input rather than a gate.
 */
{ kind: "asked"; value: Question } | 
/**
 *  A transient status line (e.g. "rate limited, retrying in 30s") shown
 *  while the run is otherwise silent; cleared by the next event.
 */
{ kind: "status"; value: string } | { kind: "runFinished"; value: string } | { kind: "runError"; value: string };

/**
 *  One request awaiting an Approve / Deny. The notch opens itself on this and
 *  draws a card. Keyed by **session id** — the `PermissionRequest` payload
 *  carries no `tool_use_id`, and the agent blocks its turn on the request, so
 *  one card per session is the protocol's own invariant. Several *sessions*
 *  can ask at once, so the panel still renders a queue.
 */
export type AgentPermission = {
	/**
	 *  The session id — how a decision is routed back to the waiting hook,
	 *  and what ties the card to its row.
	 */
	id: string,
	/**  Same as `id`; kept so the card→row linkage reads by name in the UI. */
	sessionId: string | null,
	agent: string,
	tool: string,
	/**
	 *  The tool's arguments, flattened to strings the same way sessions are —
	 *  specta will not export `serde_json::Value`.
	 */
	input: { [key in string]: string },
	cwd: string | null,
	/**
	 *  Non-empty exactly when this is an `AskUserQuestion`: the card renders
	 *  the model's own questions and options instead of Approve / Deny.
	 */
	questions: AgentQuestion[],
	/**
	 *  Whether this arrival should raise the notch — the "open notch for
	 *  permissions" setting, decided here so the webview and the window
	 *  cannot disagree. Off: the card queues quietly behind the hover.
	 */
	open: boolean,
	/**
	 *  The command is destructive (deletes data, forces state) and the card
	 *  should warn in red. Judged here, where the command is already in hand —
	 *  a heuristic nudge, not a security boundary; the full command still shows.
	 */
	danger: boolean,
};

/**  A request has been answered or the agent gave up on it; the card comes down. */
export type AgentPermissionResolved = {
	id: string,
};

/**  One question on a card, mirroring the CLI's own prompt. */
export type AgentQuestion = {
	question: string,
	/**  The short chip above the question — "Auth method", "Library". */
	header: string,
	multiSelect: boolean,
	options: AgentQuestionOption[],
};

/**  One choice under a question. */
export type AgentQuestionOption = {
	label: string,
	description: string,
};

/**
 *  One agent session, flattened for the webview.
 * 
 *  `tool_input` is deliberately absent: specta will not export
 *  `serde_json::Value`, and the running tool's arguments are arbitrary JSON.
 *  The one line worth showing is already flattened to `detail` by the scan —
 *  the same trick `agent.rs`'s `display_args()` uses.
 */
export type AgentSession = {
	/**
	 *  The agent's own session id where hooks are installed, else `pid:<n>`.
	 *  What the UI keys a tab on, so it has to be stable across polls.
	 */
	id: string,
	agent: string,
	/**  What to call the row: the model's title, the prompt, or the folder. */
	title: string,
	/**
	 *  The user's latest prompt, verbatim — what a "You:" line shows. The
	 *  title is the model's and can be a session-old summary.
	 */
	prompt: string | null,
	cwd: string | null,
	/**  The tool running right now, already flattened to one line. */
	tool: string | null,
	/**  The model, vendor prefix stripped: `opus-4-8`, `gpt-5.6-sol`. */
	model: string | null,
	/**  The git branch, for the row head: `aloud-tauri @ feat/agent-notch`. */
	branch: string | null,
	/**
	 *  ISO-8601 of last activity, for the row's `· now` / `· 10m` tag. The tag
	 *  is rendered in the webview so it updates without a new event.
	 */
	lastActivity: string | null,
	/**  Subagents spawned under this session. */
	subagents: AgentSubagent[],
	busy: boolean,
	/**
	 *  A recent one-shot stage — `"denied"` or `"session_ended"` — the webview
	 *  shows over the tool-derived stage while it lasts, else `None`.
	 */
	transient: string | null,
};

/**  The live session list, pushed whenever it actually changes. */
export type AgentSessions = AgentSession[];

/**  A subagent under a session, for the `▸ N subagents` disclosure. */
export type AgentSubagent = {
	label: string,
	model: string | null,
	tool: string | null,
	busy: boolean,
};

/**
 *  A session's full transcript, read on demand. The crate's plain
 *  [`aloud_sessions::transcript::Transcript`] flattened for the webview — same
 *  crate-logic / src-tauri-wire split as `AgentSession`.
 */
export type AgentTranscript = {
	entries: AgentTranscriptEntry[],
	/**
	 *  Token totals across the session — only in the transcript, never a hook.
	 *  `u32`: specta forbids 64-bit ints on the wire, and counts fit.
	 */
	inputTokens: number,
	outputTokens: number,
	cacheReadTokens: number,
	/**  Estimated session cost in USD, `0.0` when no priced model was seen. */
	costUsd: number | null,
};

/**
 *  One transcript entry, flattened. `kind` is a string the webview switches on
 *  ("user" | "assistant" | "toolUse"). A tool call carries its folded `result`.
 */
export type AgentTranscriptEntry = {
	kind: string,
	tool: string | null,
	text: string,
	/**
	 *  A tool call's outcome, folded onto the same entry. `None` for messages
	 *  or a still-running call.
	 */
	result: string | null,
	isError: boolean,
};

/**  One per-app override. */
export type AppRule = {
	/**  Substring of the app's name to match. Empty never matches. */
	app_matches: string,
	/**
	 *  The app's `CFBundleIdentifier`, when the rule was written by picking an
	 *  app. Additive: older rules deserialise with None and keep matching on
	 *  [`app_matches`], so there is no migration.
	 * 
	 *  [`app_matches`]: AppRule::app_matches
	 */
	bundle_id?: string | null,
	/**  Override cleanup on/off for this app. None leaves the global setting. */
	post_processing_enabled: boolean | null,
	/**  A prompt to use instead of the global one. Empty leaves the global. */
	custom_prompt: string,
};

/**
 *  What the user decided on a card, from the webview. Mirrors the terminal's
 *  own three options plus the question path.
 */
export type ApprovalReply = 
/**  "Yes" — this call only. */
{ kind: "allowOnce" } | 
/**  "Yes, don't ask again for <tool> this session." */
{ kind: "allowAlways" } | 
/**
 *  "No, and tell Claude what to do differently" — the text reaches the
 *  model as the deny message.
 */
{ kind: "deny"; message: string | null } | 
/**
 *  The answers to an `AskUserQuestion`, keyed by each question's text;
 *  multi-select answers pre-joined with `", "`.
 */
{ kind: "answer"; answers: { [key in string]: string } };

export type AudioDevice = {
	/**  Stable id, safe to persist in settings. */
	id: string,
	name: string,
};

/**  Live input level, 0.0–1.0, driving the pill's waveform. Only while recording. */
export type AudioLevel = number | null;

/**
 *  What triggers a binding.
 * 
 *  `modifiers` is side-agnostic (`Option` matches either Alt key). Only a
 *  *recording* fills `exact_modifiers`, which pins the chord to those exact
 *  keys so Left-Option+Z is not Right-Option+Z; empty means either side.
 */
export type Binding = { kind: "disabled" } | { kind: "key"; key: Key; modifiers: Modifier[]; exact_modifiers?: Key[] } | 
/**
 *  A modifier held on its own — the case Tauri's global-shortcut plugin
 *  cannot express, and why this crate exists.
 */
{ kind: "modifierKey"; key: Key; modifiers: Modifier[]; exact_modifiers?: Key[] };

/**
 *  Version, commit and build date, for pasting into a bug report. Baked in by
 *  `build.rs`; a tarball with no `.git` reports "unknown" rather than failing.
 */
export type BuildInfo = {
	version: string,
	commit: string,
	date: string,
};

/**  Which card layout draws the preview. */
export type CardKind = "message" | "email" | "event" | "task" | "note" | "issue" | "row" | "file" | "share" | "update" | "delete" | "money" | "fallback";

export type Config = {
	hold: Binding | null,
	toggle: Binding | null,
	copy_again: Binding | null,
	ask: Binding | null,
	/**
	 *  Called `command` in older settings files; `Settings::load` migrates them
	 *  rather than a serde alias, which makes specta emit a union whose
	 *  `keyof Config` is `never` and breaks the settings UI.
	 */
	rewrite: Binding | null,
	meeting_notes: Binding | null,
	agent: Binding | null,
};

/**  One connectable service, for the Connectors pane. */
export type Connector = {
	slug: string,
	name: string,
	logo: string,
	description: string,
	toolsCount: number,
	connected: boolean,
	connectionId: string | null,
};

/**
 *  Pushed when a background revalidation finds the connector list has changed —
 *  the pane paints from cache, so this is how a browser connection reaches a
 *  window that already rendered.
 */
export type ConnectorsUpdated = Connector[];

/**
 *  The shipped cleanup prompt and the date it last changed. `version` is what
 *  `Settings::seen_prompt_version` is compared against, to tell a user who
 *  forked the prompt that they are missing an improvement.
 */
export type DefaultPrompt = {
	text: string,
	version: string,
};

/**
 *  The words so far, while the live preview is on.
 * 
 *  **Feedback only — none of this is ever pasted.** It is a rolling re-read by
 *  the small local model that revises itself; the paste is a separate single
 *  pass over the whole recording once the key is up.
 */
export type DictationPartial = string;

export type Engine = 
/**  On-device whisper.cpp. No network, no API key. */
"local" | 
/**  An OpenAI-compatible endpoint (Groq by default). */
"cloud";

/**
 *  The i64s are exported as `number`: specta forbids that by default (JS loses
 *  precision past 2^53), but row ids, unix seconds and ms durations are all far
 *  below it, and BigInt would only make the frontend painful.
 */
export type Entry = {
	id: number,
	/**  Unix seconds. */
	createdAt: number,
	/**  What the transcriber returned. */
	rawTranscript: string,
	/**  What was actually pasted, after cleanup. */
	finalTranscript: string,
	appName: string | null,
	durationMs: number,
	/**
	 *  Joins this row to its `timings` spans. Null on rows written before the
	 *  column existed, so its absence is normal, not missing data.
	 */
	utteranceId: number | null,
	/**
	 *  The recording this run came from, while it survives the audio budget.
	 *  The transcript outlives the WAV, so this is often null.
	 */
	audioPath: string | null,
};

export type Field = {
	role: Role,
	/**  RFC 6901 pointer into the call's arguments. */
	path: string,
	label: string,
	value: string,
	items: string[],
	count: number,
	/**  The display name an id resolved to. */
	name: string | null,
	unresolved: boolean,
	before: string | null,
	origin: Origin | null,
	editable: boolean,
	/**
	 *  A sheet's rows as the sheet draws them: column letters first, then the
	 *  first few rows' cells. Empty for anything that is not rows of cells.
	 */
	cells: string[][],
};

/**
 *  A Finder search's results for the panel grid. The model runs the search tool
 *  itself (and speaks the count); this command is what the panel calls with the
 *  same query to draw thumbnails — so the two views stay in step without
 *  piping the tool payload back through the loop.
 */
export type FinderResults = {
	query: string,
	/**  Total matches found, which may exceed `files.len()` when truncated. */
	count: number,
	files: FoundFile[],
};

/**
 *  One file the notch grid draws for a Finder search: its path, display name,
 *  and a Quick Look thumbnail if one could be rendered.
 */
export type FoundFile = {
	path: string,
	name: string,
	/**  A `data:image/png;base64,…` preview, or None when Quick Look has none. */
	thumbnail: string | null,
};

/**  The panel's answer to a gate. */
export type GateDecision = "allowOnce" | "allowAlways" | "decline";

/**  What the user chose for one app and action. */
export type Grant = "always" | "ask" | "never";

/**
 *  What the settings pane needs to draw: whether ours are in, and who owns
 *  approvals if anyone.
 */
export type HookStatus = {
	installed: string[],
	/**  The command owning `PermissionRequest`, when it is not ours. */
	conflict: string | null,
};

/**
 *  Emitted once hotkeys are live, so the UI can clear its permission banner
 *  without the user restarting the app.
 */
export type HotkeysPermitted = boolean;

/**  An installed application, for the App Rules picker. */
export type InstalledApp = {
	/**  Display name, e.g. "Slack". */
	name: string,
	/**
	 *  `CFBundleIdentifier`, so a rule created from the picker can be keyed on
	 *  something that survives the app being renamed. None when the bundle does
	 *  not declare one.
	 */
	bundle_id: string | null,
	/**
	 *  A `data:image/png;base64,…` URI for the app icon, or None if it could
	 *  not be read. Lets the picker show icons without a second round-trip.
	 */
	icon: string | null,
};

/**
 *  A physical key, side-specific where the distinction matters — Right Option
 *  alone is a popular dictation binding.
 */
export type Key = "leftCommand" | "rightCommand" | "leftShift" | "rightShift" | "leftOption" | "rightOption" | "leftControl" | "rightControl" | 
/**  macOS only; no Windows equivalent. */
"fn" | "escape" | "space" | ({ char: string }) & { f?: never } | ({ f: number }) & { char?: never };

/**
 *  A local git repo the composer can offer, so the user picks instead of typing
 *  a path. `name` is the folder; `path` is what `start_coding_agent` takes.
 */
export type LocalRepo = {
	name: string,
	path: string,
};

export type Macro = {
	/**  The spoken phrase that triggers expansion, e.g. "my address". */
	trigger: string,
	expansion: string,
};

export type MeetingPhase = 
/**
 *  Re-emitted as each chunk finishes so the readout re-syncs instead of
 *  drifting off a single start event.
 */
{ phase: "recording"; elapsedSecs: number; words: number } | { phase: "saving" } | { phase: "idle" };

/**
 *  Model download progress, 0.0–1.0. First use of the local engine fetches
 *  ~150MB; without this the pill sits on "Transcribing…" for minutes and the
 *  app looks hung.
 */
export type ModelDownload = number | null;

export type Modifier = "command" | "control" | "option" | "shift" | "function";

/**
 *  Whether the pointer is over the notch.
 * 
 *  The window ignores the mouse while it is click-through, and a window that
 *  ignores the mouse cannot see it move — so the webview has no `mouseenter` to
 *  listen for and the hover has to be pushed in from the cursor poll.
 */
export type NotchHover = {
	over: boolean,
};

export type Note = {
	path: string,
	title: string,
	/**
	 *  Unix seconds; parsed from the file name, falling back to file mtime.
	 *  Exported as `number` — specta forbids i64 by default over JS precision
	 *  loss past 2^53, which a unix second is nowhere near.
	 */
	date: number,
	content: string,
};

/**  Whose words a text field holds. */
export type Origin = 
/**  The user said it. */
"yours" | 
/**  The model wrote it. */
"aloud";

/**
 *  Tells the overlay to play its exit, ahead of the window actually going away:
 *  the pill collapses while the window is still up, and [`hide`] takes the
 *  window away once it has.
 */
export type OverlayDismiss = null;

/**
 *  Which monitor the overlay appears on. `Named` stores the OS name, not an
 *  index: indices are reassigned on unplug, so a saved index changes meaning.
 *  A name that no longer resolves falls back to the primary.
 */
export type OverlayDisplay = 
/**  The monitor holding the cursor. */
"active" | "primary" | { named: string };

/**
 *  Why a dictation failed, in words the user can act on. `Phase::Error` says
 *  only that something broke, which the pill used to render as "Failed".
 */
export type OverlayError = string;

/**
 *  How the recording overlay draws itself. `DropPill` grows out of the notch
 *  and has room for content; `Wings` are two menu-bar tabs (macOS only, and
 *  they fall back to the pill with no notch or text too long for a 40pt tab).
 * 
 *  `DropPill` serializes as `dropPill`, never the `pill` its name suggests:
 *  `pill` was the retired glass capsule's stored name, and the collision made
 *  this style revert on every restart — see
 *  `the_drop_down_pill_survives_a_restart`.
 */
export type OverlayStyle = "dropPill" | "wings";

/**
 *  The style the overlay window should draw, pushed on every show — the overlay
 *  has no settings binding of its own. Notch fields are zero when not welding.
 */
export type OverlayStyleChanged = {
	style: OverlayStyle,
	/**  Logical-pixel width of the notch gap between the two wings. */
	notchWidth: number | null,
	/**  Logical-pixel height of the wings, matching the notch's safe-area inset. */
	notchHeight: number | null,
};

/**  A capability the app needs the OS to allow. */
export type Permission = 
/**  Global hotkeys, synthetic paste, and reading the focused selection. */
"accessibility" | "microphone";

/**  One app and action in the Settings pane, with what Aloud may do there. */
export type PermissionRow = {
	key: string,
	app: string,
	action: string,
	grant: Grant,
	/**  "Always allow" can never apply, so the row offers Ask or Never only. */
	strict: boolean,
};

export type PermissionStatus = {
	permission: Permission,
	granted: boolean,
};

export type Phase = "idle" | 
/**
 *  Always-listening is on and nothing is being said: the wings sit in the
 *  menu bar. Never set by a dictation; see `crate::listen`.
 */
"listening" | "recording" | "transcribing" | "done" | 
/**
 *  Silence or filler only — a normal result, but its own phase rather than
 *  `Idle` so the overlay can say so instead of claiming "Pasted".
 */
"noSpeech" | "error";

/**
 *  A tool the run intends to call. No arguments: they arrive with the call
 *  itself, which is where it stops being a plan and starts being an action.
 */
export type PlannedCall = {
	name: string,
	app: string,
};

/**
 *  A question put to the user mid-run. `options` non-empty means the answer is
 *  one of them, so the panel offers buttons instead of a text field.
 */
export type Question = {
	question: string,
	options: string[],
};

/**  The whole quota, as the dashboard shows it. */
export type Quota = {
	fiveHour: QuotaWindow | null,
	sevenDay: QuotaWindow | null,
	sevenDayOpus: QuotaWindow | null,
	extraUsagePercent: number | null,
};

/**  One rolling limit window, flattened for the webview. */
export type QuotaWindow = {
	/**  0–100. */
	percent: number | null,
	/**
	 *  ISO-8601 reset time; the webview renders the countdown so it ticks
	 *  without a refetch.
	 */
	resetsAt: string | null,
};

/**  What a field is, which decides how the card draws it. */
export type Role = 
/**  Where a message goes: a channel or chat. */
"destination" | 
/**  Who it goes to: an address or attendee list. */
"person" | "heading" | 
/**
 *  A date or time, already formatted. On an event, `items[0]` is the line
 *  under it: time zone and length.
 */
"when" | 
/**  Body text, shown in full and never truncated. */
"text" | 
/**  An amount with its currency folded in, in major units. */
"money" | "path" | 
/**  `value` is the full host; `items[0]` the whole URL. */
"url" | 
/**  An opaque identifier nothing has named yet. */
"id" | 
/**  One of a schema `enum`. */
"pill" | 
/**  An array or object: `count` entries, the first few in `items`. */
"list" | 
/**  A boolean that differs from its default. */
"flag" | "plain";

/**
 *  A less destructive tool the card can offer instead, e.g. Trash over a
 *  permanent delete.
 */
export type Safer = {
	label: string,
	tool: string,
};

export type SearchResult = {
	note: Note,
	score: number,
	/**  Text around the first body match, for the results list. */
	snippet: string,
};

/**
 *  Everything the app remembers between launches. One coarse struct rather
 *  than ~70 commands: it is a few hundred bytes and the frontend gets one
 *  `get`/`update` pair.
 */
export type Settings = {
	groqApiKey?: string,
	composioApiKey?: string,
	/**
	 *  Gemini key: the last brain commands fall back to — see
	 *  `aloud_agent::brains` for the order.
	 */
	geminiApiKey?: string,
	/**
	 *  Cerebras key. Off the brain list while its account is unpaid; the eval
	 *  still reaches it by name.
	 */
	cerebrasApiKey?: string,
	/**  NVIDIA key: the brain behind Groq, for when Groq's per-minute budget trips. */
	nvidiaApiKey?: string,
	/**
	 *  Deepgram key. Always-listening streams the mic to Deepgram's Flux, which
	 *  decides where a spoken request ends; without it the mode falls back to a
	 *  pause detector and local whisper.
	 */
	deepgramApiKey?: string,
	engine?: Engine,
	transcriptionModel?: string,
	baseUrl?: string,
	/**  BCP-47 code, or empty to auto-detect. */
	language?: string,
	/**
	 *  Live-transcript preview. Changes nothing about what gets pasted — see
	 *  [`aloud_transcribe::preview`]. Off by default: it runs the local model
	 *  several times a second, which is real CPU and battery on a laptop.
	 */
	streamingTranscription?: boolean,
	postProcessingEnabled?: boolean,
	postProcessingModel?: string,
	fallbackModel?: string,
	/**  Overrides the built-in cleanup prompt when non-empty. */
	customSystemPrompt?: string,
	/**
	 *  Version of the built-in prompt the user last acknowledged; empty means
	 *  never, so a pre-existing install sees the offer once.
	 */
	seenPromptVersion?: string,
	/**
	 *  Language the pasted text is written in — distinct from [`language`],
	 *  the language *spoken*. Cleanup applies it; transcription never sees it.
	 * 
	 *  [`language`]: Settings::language
	 */
	outputLanguage?: string,
	/**
	 *  Reject a cleanup that *answered* the transcript instead of tidying it —
	 *  see [`aloud_llm::guard`]. On by default: it catches pasting text the
	 *  user never dictated, and a false positive only costs the raw transcript.
	 */
	instructionGuardEnabled?: boolean,
	/**
	 *  Proper nouns and jargon fed to the model as a spelling reference, and to
	 *  the transcriber as a recognition bias. See `aloud_transcribe::bias_prompt`.
	 */
	vocabulary?: string[],
	/**
	 *  Phrases cleanup must return exactly as spoken — no filler removal, no
	 *  rewording, no punctuation "fixes" inside them.
	 * 
	 *  Distinct from [`vocabulary`], which only steers *spelling* and leaves the
	 *  model free to tidy the sentence around it. "I am um boss" needs the "um"
	 *  kept, and the filler rule would otherwise delete it.
	 * 
	 *  [`vocabulary`]: Settings::vocabulary
	 */
	preservePhrases?: string[],
	/**  Spoken shorthand that expands to canned text after cleanup. */
	macros?: Macro[],
	/**  Per-app behaviour overrides, applied by the focused app's name. */
	appRules?: AppRule[],
	/**
	 *  Whether a selection can turn a dictation into a rewrite. A selection is
	 *  the *only* signal — no extra-modifier gesture, which collided with the
	 *  dictate key. Explicit rewrite is [`aloud_hotkey::model::Role::Rewrite`].
	 * 
	 *  On by default: the feature shipped with no toggle, so defaulting to off
	 *  would silently remove it from every existing user.
	 */
	commandModeEnabled?: boolean,
	hotkeys?: Config,
	selectedMicrophone?: string | null,
	playSounds?: boolean,
	/**
	 *  Alert-chime volume, 0.0–1.0. Honoured on macOS (`afplay -v`); Windows
	 *  system sounds have no per-sound volume, so it is ignored there.
	 */
	soundVolume?: number | null,
	pressEnterCommand?: boolean,
	/**
	 *  Delay before capture begins, so a key still travelling does not clip the
	 *  first syllable. 0 disables.
	 */
	shortcutStartDelayMs?: number,
	/**
	 *  Silence system output while recording. Restored when capture stops, and
	 *  on the next launch if the app died first. macOS only.
	 */
	muteSystemAudio?: boolean,
	/**
	 *  Show the menu-bar icon. Hiding it leaves hotkeys working; opening the app
	 *  again is the way back to the window (macOS turns that into a reopen).
	 */
	showMenuBarIcon?: boolean,
	/**  Drop-down pill or menu-bar wings; wings are macOS-only. */
	overlayStyle?: OverlayStyle,
	/**
	 *  Whether a coding agent's permission request opens the notch by itself.
	 *  Off means the request waits quietly — the Agents surface flags it, and
	 *  the user opens the notch when they hover. The hook waits either way.
	 */
	agentOpenOnPermission?: boolean,
	overlayDisplay?: OverlayDisplay,
	/**
	 *  Put the previous clipboard back after pasting. Off leaves the dictated
	 *  text on the clipboard so it can be pasted again.
	 */
	preserveClipboard?: boolean,
	/**  Whether the first-run wizard has been completed. False shows it. */
	onboarded?: boolean,
	/**
	 *  Reveals the latency waterfall. A runtime toggle, not a build-time flag,
	 *  which made it unreachable in every release users actually run.
	 */
	developerTools?: boolean,
	historyRetention?: number,
	/**
	 *  Disk the kept recordings may use, in MB. 0 keeps none, which also
	 *  removes the Run Log's player and retry — both read the WAV.
	 */
	audioRetentionMb?: number,
	/**
	 *  Evict recordings older than this many days regardless of the size
	 *  budget. 0 leaves size as the only limit.
	 */
	audioRetentionDays?: number,
	/**
	 *  Master switch for the meme cats. Off hides every cat everywhere; the
	 *  per-place flags below only matter while this is on. On by default —
	 *  the cats are the personality, opting out is the exception.
	 */
	catImages?: boolean,
	/**  The "I am listening" cat that rides the notch during a live dictation. */
	catImagesDictation?: boolean,
	/**
	 *  The stage cats on the agents surface — the ambient strip, the dealt
	 *  notch cards, the agent list and its hover peek.
	 */
	catImagesAgents?: boolean,
};

/**
 *  A note id in Notes, a saved file, a folder in the app that opened it — for
 *  [`show_result`]. The tools work in the background, so this is the way back.
 */
export type ShowTarget = {
	app: string,
	target: string,
};

/**  One closed span. */
export type Span = {
	/**  Groups the stages of one dictation; monotonic, so it orders by time. */
	utteranceId: number,
	/**  The span name: `utterance`, `transcribe`, `cleanup`, … */
	stage: string,
	/**  Unix milliseconds at span entry — the waterfall's x offset. */
	startedAt: number,
	durationMs: number,
	success: boolean,
	/**  The span's fields, as JSON. */
	fields: string,
};

/**  See [`crate::history::Entry`] on why u64 exports as `number`. */
export type Stats = {
	totalWords?: number,
	totalSessions?: number,
	totalSpokenSeconds?: number | null,
	currentStreakDays?: number,
	bestStreakDays?: number,
	/**
	 *  Local calendar day of the last dictation, as `YYYY-MM-DD`. A string so it
	 *  crosses the specta boundary; [`Self::last_day`] parses it back.
	 */
	lastDictationDay?: string | null,
};

/**
 *  [`Stats`] plus the values derived from it. Derived here rather than stored
 *  or re-derived in TS, so the formula has exactly one home.
 */
export type StatsView = {
	timeSavedSeconds: number | null,
} & Stats;

/**
 *  How hard the card makes it to say yes. Default-Always grants never reach a
 *  card, so there is no tier below Confirm.
 */
export type Tier = "confirm" | 
/**  Red, needs a click, never auto-runs, and "Always allow" cannot cover it. */
"strict";

/**
 *  A tool call for display. Kept separate from `ParsedAction` so the UI
 *  contract does not leak parser internals.
 */
export type ToolCall = {
	/**  e.g. "github.create_issue". */
	name: string,
	/**  The target app, e.g. "github". */
	app: string,
	/**
	 *  Args as strings, not `serde_json::Value`: specta refuses to export its
	 *  i64-backed number type. Non-string values keep their JSON form.
	 */
	args: { [key in string]: string },
	/**  Whether this call pauses for confirmation before it runs (every write). */
	requiresConfirmation: boolean,
	/**
	 *  What the gate's card shows, read from the real arguments. Only on the
	 *  gate event; the start event and reads carry none. Boxed so every other
	 *  event is not sized to the card.
	 */
	preview: ActionPreview | null,
	/**
	 *  The gate may offer "Always allow": false for strict actions and for a
	 *  write outside content asked for.
	 */
	canAlways: boolean,
	/**
	 *  The loop's step for this call: a round's calls all start before any
	 *  finishes, so a result finds its row by this. None on the fast path.
	 */
	id?: number | null,
};

export type ToolResult = {
	success: boolean,
	message: string,
	/**  What the row's Show button brings back, when the step made something. */
	show: ShowTarget | null,
	/**
	 *  A line the row keeps under it: why a saved grant refused the step. A
	 *  status line would be wiped by this very result.
	 */
	note: string | null,
	/**  The folder a tidy-up sorted, which the row's Undo puts back. */
	tidied: string | null,
	/**  The [`ToolCall::id`] this result finishes. */
	id?: number | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

